contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Send an amount to c via Deposit and assert the atomic balance update property.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // read before-values
        uint beforeRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeEth = address(c).balance;

        // perform Deposit and catch whether it reverted
        bool reverted;
        c.Deposit{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-values
        uint afterRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterEth = address(c).balance;

        // General rule: if Deposit did not revert then both the stored balance and contract ETH
        // increased by exactly amount; if it reverted then neither may have increased by amount.
        // We express the asserted property as: either reverted is true, or both increases equal amount.
        assert(reverted || (afterRecorded == beforeRecorded + amount && afterEth == beforeEth + amount));
    }

    receive() external payable { }
}

